		{"urlscheme https", &context{request: &http.Request{Header: http.Header{HeaderXUrlScheme: []string{"https"}}}}, "https"},
		{"empty", &context{request: &http.Request{}}, "http"},
		{
			"ignores invalid X-Forwarded-Proto and uses X-Forwarded-Protocol",
