package echo

import (
	"fmt"
	"net/http"
	"reflect"
	"testing"
)

func dump(n *node, depth int) {
	if n == nil {
		return
	}
	fmt.Printf("%*skind=%d label=%q prefix=%q ppath=%q pnames=%v handler=%v\n", depth*2, "", n.kind, string(n.label), n.prefix, n.ppath, n.pnames, n.findHandler(http.MethodGet) != nil)
	for _, c := range n.staticChildren {
		dump(c, depth+1)
	}
	if n.paramChild != nil {
		fmt.Printf("%*s(paramChild)\n", (depth+1)*2, "")
		dump(n.paramChild, depth+2)
	}
	if n.anyChild != nil {
		fmt.Printf("%*s(anyChild)\n", (depth+1)*2, "")
		dump(n.anyChild, depth+2)
	}
}

