func TestZZStale(t *testing.T) {
	e := New()
	r := e.router
	r.Add(http.MethodGet, "/users/:id", func(c Context) error { c.Set("hit", "users"); return nil })
	r.Add(http.MethodGet, "/users/:id/files/:fid", func(c Context) error { c.Set("hit", "files"); return nil })

	c := e.NewContext(nil, nil).(*context)
	r.Find(http.MethodGet, "/users/1/files/2", c)
	fmt.Printf("1st: path=%q pnames=%v pvalues=%v handler!=nil=%v\n", c.Path(), c.ParamNames(), c.ParamValues(), c.Handler() != nil)

	// now a non-routable path with the same context
	r.Find(http.MethodGet, "/nonexistent", c)
	fmt.Printf("2nd: path=%q pnames=%v pvalues=%v param(id)=%q param(fid)=%q\n", c.Path(), c.ParamNames(), c.ParamValues(), c.Param("id"), c.Param("fid"))
	err := c.Handler()(c)
	fmt.Printf("2nd handler err=%v hit=%v\n", err, c.Get("hit"))

	// via ServeHTTP twice (pooled context)
	e2 := New()
	e2.GET("/users/:id", func(c Context) error { return c.String(200, "u:"+c.Param("id")) })
	fmt.Println("ServeHTTP /users/1 ->", serve(e2, "/users/1"))
	fmt.Println("ServeHTTP /nope    ->", serve(e2, "/nope"))
	fmt.Println("ServeHTTP /users/1 ->", serve(e2, "/users/1"))
	fmt.Println("ServeHTTP /nope    ->", serve(e2, "/nope"))
}

func serve(e *Echo, path string) string {
	req, _ := http.NewRequest(http.MethodGet, path, nil)
	rec := newRecorder()
	e.ServeHTTP(rec, req)
	return fmt.Sprintf("%d %s", rec.Code, rec.Body.String())
}
